        for (int j = len - 1; j >= 0; j--) {
            arr[j] = code % base;
            code /= base;
        }
    }

    void runProgram() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        if (n < m) {
            int temp = n; n = m; m = temp;
        }
        int totalStates = 1;
        for (int j = 0; j < m; j++) totalStates *= 3;
        int[] dp = new int[totalStates];
        int[] tempDp = new int[totalStates];
        int[] arrA = new int[m];
        int[] arrB = new int[m];
        Arrays.fill(arrA, 1);
