                            arrB[j] = 2;
                            countOnes++;
                        }
                    }
                    for (int j = 0; j < m; j++) {
                        if (arrB[j] == 0 && (arrA[j] == 2 || (j > 0 && arrB[j - 1] == 2) || (j + 1 < m && arrB[j + 1] == 2))) {
                            arrB[j] = 1;
                        }
                    }
                    int newIdx = encode(arrB, m);
                    tempDp[newIdx] = Math.max(tempDp[newIdx], dp[index] + m - countOnes);
                }
            }
            int[] swapTemp = dp; dp = tempDp; tempDp = swapTemp;
        }
        int maxVal = 0;
        for (int idx = 0; idx < totalStates; idx++) {
