#include <bits/stdc++.h>
using namespace std;

int encode(const vector<int>& arr, int len) {
    int val = 0;
    for (int i = 0; i < len; i++) {
        val = val * 3 + arr[i];
    }
    return val;
}

void decode(vector<int>& arr, int len, int code, int base) {
    for (int j = len - 1; j >= 0; j--) {
        arr[j] = code % base;
        code /= base;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    if (n < m) {
        int temp = n; n = m; m = temp;
    }
    int totalStates = 1;
    for (int j = 0; j < m; j++) totalStates *= 3;
    vector<int> dp(totalStates, -1);
    vector<int> tempDp(totalStates, -1);
    vector<int> arrA(m, 1);
    vector<int> arrB(m);
    dp[encode(arrA, m)] = 0;
    while (n-- > 0) {
        std::fill(tempDp.begin(), tempDp.end(), -1);
        for (int index = 0; index < totalStates; index++) {
            if (dp[index] < 0) continue;
            vector<int> currentArrA(m);
            decode(currentArrA, m, index, 3);
            for (int mask = 0; mask < (1 << m); mask++) {
                for (int j = 0; j < m; j++) {
                    arrB[j] = (mask & (1 << j)) ? 1 : 0;
                }
                bool invalid = false;
                for (int j = 0; j < m; j++) {
                    if (currentArrA[j] == 0 && arrB[j] == 0) {
                        invalid = true;
                        break;
                    }
                }
                if (invalid) continue;
                int countOnes = 0;
                for (int j = 0; j < m; j++) {
                    if (arrB[j] == 1) {
                        arrB[j] = 2;
                        countOnes++;
                    }
                }
                for (int j = 0; j < m; j++) {
                    if (arrB[j] == 0 && (currentArrA[j] == 2 || (j > 0 && arrB[j - 1] == 2) || (j + 1 < m && arrB[j + 1] == 2))) {
                        arrB[j] = 1;
                    }
                }
                int newIdx = encode(arrB, m);
                if (tempDp[newIdx] < dp[index] + m - countOnes) {
                    tempDp[newIdx] = dp[index] + m - countOnes;
                }
            }
        }
        swap(dp, tempDp);
    }
    int maxVal = 0;
    for (int idx = 0; idx < totalStates; idx++) {
        if (dp[idx] <= maxVal) continue;
        vector<int> arrA(m);
        decode(arrA, m, idx, 3);
        bool bad = false;
        for (int j = 0; j < m; j++) {
            if (arrA[j] == 0) {
                bad = true;
                break;
            }
        }
        if (!bad) maxVal = dp[idx];
    }
    cout << maxVal << "\n";
    return 0;
}
